changeSet.sql:
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '${svcRole}') THEN
        CREATE ROLE ${svcRole} LOGIN PASSWORD '${svcPass}' NOSUPERUSER NOBYPASSRLS;
    END IF;
END
$$;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'nexus_svc') THEN
        CREATE ROLE nexus_svc LOGIN PASSWORD 'nexus_svc_pass' NOSUPERUSER NOBYPASSRLS;
    END IF;
END
$$;

GRANT USAGE ON SCHEMA nexus TO ${svcRole};
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA nexus TO ${svcRole};
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA nexus TO ${svcRole};

-- nexus-cbo4a batch 1b: topics_id_seq additionally needs UPDATE (not just
-- USAGE/SELECT) -- importTopic-style fidelity paths call
-- setval(pg_get_serial_sequence(...), GREATEST(last_value, ?)) to keep the
-- sequence ahead of a client-supplied id, mirroring production's own
-- taxonomy-005-topics-seq-update-grant.xml (GRANT UPDATE ... TO nexus_svc).
-- Three test classes previously hand-granted this identical statement; no
-- test in the repo relies on this sequence's UPDATE being ABSENT, so it is
-- safe to widen here once instead of per-class.
GRANT UPDATE ON SEQUENCE nexus.topics_id_seq TO ${svcRole};

GRANT USAGE ON SCHEMA staging TO ${svcRole};
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE ON ALL TABLES IN SCHEMA staging TO ${svcRole};

-- nexus-cbo4a batch 13 (fts_matches): the Plans/Memory schema tests probe a
-- table's fts_vector THROUGH TenantScope.withTenant, i.e. as ${svcRole}, and
-- the probe is the test-lifecycle function nexus_test.fts_matches (the jOOQ
-- typed replacement for a condition("... @@ plainto_tsquery(...)") template).
-- A plain LOGIN role has no USAGE on nexus_test, so the call failed with
-- "permission denied for schema nexus_test" on the first full-suite run of
-- that conversion. Grant schema USAGE plus EXECUTE on that ONE function --
-- not ALL FUNCTIONS: the other nexus_test objects are DDL/grant helpers meant
-- for the superuser owner connection only (see db.changelog-test-objects.xml).
GRANT USAGE ON SCHEMA nexus_test TO ${svcRole};
GRANT EXECUTE ON FUNCTION nexus_test.fts_matches(tsvector, text, text) TO ${svcRole};
